def process_user_data(data):
    res = []
    for x in data:
        if x['active'] == True:
            res.append(x['name'].upper())
    return res

def fib(n):
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    return fib(n-1) + fib(n-2)

def aggregate_logs(logs):
    out = ''
    for log in logs:
        if 'ERROR' in log:
            out += log.strip() + '\n'
    return out

def append_to_list(element, target_list=[]):
    target_list.append(element)
    return target_list

def read_first_line(filepath):
    f = open(filepath, 'r')
    data = f.readline()
    return data.strip()

def total_price(cart):
    total = 0
    for item in cart:
        total = total + item['price'] * item['qty']
    return total

def group_by_id(records):
    res = {}
    for r in records:
        k = r['id']
        if k not in res:
            res[k] = []
        res[k].append(r['value'])
    return res

def parse_ages(age_strings):
    ages = []
    for s in age_strings:
        ages.append(int(s))
    return ages

def get_unique_evens(numbers):
    seen = []
    for n in numbers:
        if n % 2 == 0:
            if n not in seen:
                seen.append(n)
    return seen

def check_access(user, permission):
    if 'permissions' in user:
        return permission in user['permissions']
    return False

def safe_division(a, b):
    try:
        return a / b
    except:
        return None
